llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Indomethacin, a high-transfer analogue sharing the chloroindole and methoxyaryl motifs, has 98% absolute oral bioavailability in adults, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Rigosertib, a high-transfer trimethoxyphenyl analogue, has 35% absolute oral bioavailability after a single fasting oral dose in patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Omeprazole, a high-transfer heteroaromatic analogue, has 30–40% absolute oral bioavailability versus IV, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Alfuzosin, a high-transfer dimethoxyquinazoline diamine analogue, has 64% mean oral bioavailability in healthy volunteers, strongly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Colchicine, a high-transfer polymethoxy/amide analogue, has mean absolute oral bioavailability ~55% in elderly subjects, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Midodrine, a high-transfer dimethoxyphenyl analogue, has 93% absolute bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "5-Hydroxytryptophan, a high-transfer indole analogue, has 49% absolute bioavailability after oral dosing, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib in fed patients had 13.9% absolute bioavailability, a sub-20% value, but this is fed-state/formulation-specific and outweighed by fasting 35% and other high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: multiple high-transfer analogues with direct absolute oral bioavailability measurements cluster at 30–100%, well above the 20% threshold; the only sub-20% values are condition-specific (fed state, neonates) and not representative.",
  "evidence_gaps": [
    "No direct pharmacokinetic study for the query molecule itself.",
    "Fed-state and paediatric extremes in analogues create uncertainty about the exact F value, though not about the ≥20% classification.",
    "The query's larger, more polar structure may have solubility/efflux liabilities not fully captured by the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

